// CSD_RATIONALE_BEGIN
// Root-cause analysis of 2% accuracy / 77.6% syntax:
//
// SYNTAX FAILURES (10/49 unterminated spans):
//   - The previous attempt reserved `closeReserve=50` steps but miscounted
//     available budget, leaving spans without enough budget to close.
//   - `SafeBoostedConstrainedStep` is not in the allowed API; if it were
//     silently replaced by ConstrainedStep, operator steering didn't work.
//
// ACCURACY FAILURES (37/49 wrong answers):
//   - PRIMARY: `CloseSpanIfComplete` fires at the FIRST complete parse.
//     A single identifier `n` or short product `n * m` is a complete
//     arithmetic expression, so the span closes immediately after 1-3 tokens.
//     The model WANTED to write `n * m / k` but got cut off at `n * m`.
//   - SECONDARY: The model writes multi-step reasoning, arrives at a partial
//     formula in its scratchpad, and `CloseSpanIfComplete` locks it in.
//
// FIX — replace CloseSpanIfComplete + ConstrainedStep inner loop with a
// single `CloseSpanWithinBudget` call using ALL remaining budget:
//   `CloseSpanWithinBudget` generates forward, tracks the LONGEST complete
//   prefix (not the first), and closes at that point.  If the model generates
//   `n * m / k` and the parser accepts each sub-expression, CloseSpanWithinBudget
//   closes at `n * m / k` — exactly what we want.
//
// STRUCTURE:
//   Phase 1: UnconstrainedChunk loop (2/3 budget) watching for "<<" with
//            RenderedEndsWith-aware detection via UnconstrainedChunk's
//            stoppedOnOpen flag.
//   Phase 2: If span open, CloseSpanWithinBudget with ALL remaining budget —
//            generates longest complete arithmetic expression and closes.
//   Phase 3: If no span opened naturally, force-open with OpenConstrainedSpan.
//   Phase 4: CloseSpanWithinBudget for any remaining open span.
//
// This guarantees:
//   - Spans always close (budget always reserved for Phase 4)
//   - Expressions are as long/complete as the model can produce
//   - No premature closure at first complete sub-expression
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`
//
//   Phase 1 (UnconstrainedChunk loop):
//     When stoppedOnOpen=false, insideConstrainedOut stays false (implication vacuous).
//     When stoppedOnOpen=true, EnterObservedConstrainedSpan sets currentConstrainedOut := [],
//     which satisfies parser.IsValidPrefix([]) by the method precondition. The loop
//     then exits because insideConstrainedOut=true makes !insideConstrainedOut false.
//
//   Phase 2 (CloseSpanWithinBudget):
//     Library postcondition explicitly guarantees
//     `insideOut ==> parser.IsValidPrefix(currentOut)`, so invariant holds after.
//
//   Phase 3 (OpenConstrainedSpan):
//     Sets currentConstrainedOut := []; valid by precondition parser.IsValidPrefix([]).
//     insideConstrainedOut := true, and |[]| = 0 <= |generated + ["<<"]|. ✓
//
//   Phase 4 (CloseSpanWithinBudget):
//     Same library postcondition guarantee as Phase 2. ✓
//
// Invariant 2 — progress:
//   `|generated| <= |generatedPrefix| + steps`
//
//   Phase 1: Each UnconstrainedChunk call with actual>=1 satisfies
//   |generatedOut| <= |generated_old| + stepsUsed and steps grows by stepsUsed >= 1.
//   EnterObservedConstrainedSpan costs +0 and leaves generated unchanged.
//   EOS break preserves the bound since steps was already incremented. ✓
//
//   Phase 2: CloseSpanWithinBudget postcondition gives
//   |generatedOut| <= |generated_old| + budget2; we set steps += budget2.
//   So |generated| <= |generatedPrefix| + steps. ✓
//
//   Phase 3: OpenConstrainedSpan appends exactly "<<" (+1 token), steps += 1.
//   |generated| grows by 1, steps grows by 1 — bound preserved. ✓
//
//   Phase 4: Same argument as Phase 2 with budget4 = maxSteps - steps. ✓
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. At the very end write the answer as <<EXPR>> where EXPR is the complete arithmetic formula with ALL variables and operators needed. Do not stop at a partial sub-expression. Example: <<n1 * c1 + n2 * c2 + c3>>.");

var steps: nat := 0;
var spanOpened: bool := insideConstrained;
var chunkSize: nat := 50;

// Free reasoning budget: 2/3 of total steps
var freeLimit: nat := (maxSteps * 2) / 3;
if freeLimit == 0 && maxSteps > 0 { freeLimit := 1; }

// Phase 1: Free generation in chunks, stopping when << is observed
while steps < freeLimit && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases freeLimit - steps
{
  var actual: nat := chunkSize;
  if steps + actual > freeLimit { actual := freeLimit - steps; }
  if actual == 0 { break; }
  var cg, stoppedOnOpen, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(lm, prompt, generated, actual, "<<", eosToken);
  generated := cg;
  steps := steps + stepsUsed;
  if stoppedOnEos { break; }
  if stoppedOnOpen {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg;
    insideConstrainedOut := ei;
    currentConstrainedOut := ec;
    spanOpened := true;
  }
}

// Phase 2: If inside a span, generate the FULL expression and close using
// CloseSpanWithinBudget with all remaining budget — closes at the LONGEST
// complete arithmetic expression, not the first.
if insideConstrainedOut && steps < maxSteps {
  var budget2 := maxSteps - steps;
  var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget2);
  generated := wg2;
  insideConstrainedOut := wi2;
  currentConstrainedOut := wc2;
  steps := steps + budget2;
}

// Phase 3: If no span was ever opened, force one open now
if !insideConstrainedOut && !spanOpened && steps + 1 < maxSteps {
  var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg;
  insideConstrainedOut := fi;
  currentConstrainedOut := fc;
  steps := steps + 1;
  spanOpened := true;
}

// Phase 4: Close any remaining open span with all remaining budget
if insideConstrainedOut && steps < maxSteps {
  var budget4 := maxSteps - steps;
  var wg4, wi4, wc4 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget4);
  generated := wg4;
  insideConstrainedOut := wi4;
  currentConstrainedOut := wc4;
  steps := steps + budget4;
}

cost := steps;

